  "wiki_only_topics": [
    {
      "topic": "Etymology of the word by-law from Old Norse bȳlǫg and Danelaw town law",
      "quote_wikipedia": "The Merriam-Webster Dictionary indicates that the origin of the word by-law is from the English word bilawe, probably from Old Norse *bȳlǫg, from Old Norse bȳr town + lag-, lǫg law. The earliest use of the term originates from the Viking town law in the Danelaw, wherein by is the Old Norse word for a larger settlement as in Whitby and Derby (compare with the modern Danish-Norwegian word by meaning town, or the modern Swedish word by, meaning village)."
    },
    {
      "topic": "Municipal by-laws as delegated legislation enforceable with penalties",
      "quote_wikipedia": "Municipal by-laws are public regulatory laws; which apply in a certain area. The main difference between a by-law and a law passed by a national/federal or regional/state body is that a by-law is made by a non-sovereign body, which derives its authority from another governing body, and can only be made on a limited range of matters."
    },
    {
      "topic": "By-laws in Japan under Article 94 of the Constitution and the Local Autonomy Law",
      "quote_wikipedia": "Under Article 94 of the Constitution of Japan, regional governments have limited autonomy and legislative powers to create by-laws. In practice, such powers are exercised in accordance with the Local Autonomy Law."
    },
    {
      "topic": "By-laws in the United Kingdom as delegated legislation made by local councils under acts of Parliament",
      "quote_wikipedia": "In the United Kingdom, by-laws are laws of local or limited application made by local councils or other bodies, using powers granted by an act of Parliament, and so are a form of delegated legislation."
    },
    {
      "topic": "Corporate and organizational by-laws covering officers, meetings, and amendment procedures",
      "quote_wikipedia": "By-laws widely vary from organization to organization, but generally cover topics such as the purpose of the organization, who are its members, how directors are elected, how meetings are conducted, and what officers the organization will have and a description of their duties."
    }
  ]
